SELECT CAST(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN ad.admittime AND (ad.dischtime - interval '48 hours') AND emar.medication ILIKE '%GLP-1%' THEN emar.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT ad.subject_id), 0) AS proportion_first_48_hours, CAST(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN (ad.dischtime - interval '24 hours') AND ad.dischtime AND emar.medication ILIKE '%GLP-1%' THEN emar.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT ad.subject_id), 0) AS proportion_final_24_hours, CAST(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN ad.admittime AND (ad.dischtime - interval '48 hours') AND emar.medication ILIKE '%GLP-1%' THEN emar.subject_id END) AS FLOAT) - NULLIF(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN (ad.dischtime - interval '24 hours') AND ad.dischtime AND emar.medication ILIKE '%GLP-1%' THEN emar.subject_id END), 0) AS net_change FROM admissions ad JOIN patients pt ON ad.subject_id = pt.subject_id JOIN emar ON ad.subject_id = emar.subject_id WHERE pt.gender = 'M' AND pt.anchor_age BETWEEN 56 AND 66 AND EXISTS (SELECT 1 FROM diagnoses_icd d WHERE d.subject_id = ad.subject_id AND d.icd_code IN ('440', '448')) AND EXISTS (SELECT 1 FROM procedures_icd p WHERE p.subject_id = ad.subject_id AND p.icd_code IN ('440', '448'));